class Point:
    __slots__ = ("x", "y")

    def __init__(self, x, y):
        self.x, self.y = x, y

    def __eq__(self, other):
        if not isinstance(other, Point):
            return NotImplemented
        return (self.x, self.y) == (other.x, other.y)

    def __hash__(self):
        return hash((self.x, self.y))

p = Point(1, 2)
s = {Point(1, 2)}
print(p in s, p == Point(1, 2))  # True True

class Playlist:
    def __init__(self, songs):
        self._songs = list(songs)

    def __len__(self):
        return len(self._songs)

    def __iter__(self):
        return iter(self._songs)

    def __contains__(self, x):
        return x in self._songs

    def __getitem__(self, i):
        return self._songs[i]

    def __repr__(self):
        return f"Playlist({self._songs!r})"

    def __eq__(self, other):
        if not isinstance(other, Playlist):
            return NotImplemented
        return self._songs == other._songs

pl = Playlist(["a", "b", "c"])
print(len(pl), list(pl), "b" in pl, pl[0], pl[1:3], pl == Playlist(["a", "b", "c"]), repr(pl))

import json
from collections.abc import MutableSequence

class JsonMixin:
    def to_json(self):
        return json.dumps(self._items, ensure_ascii=False)

class Bag(JsonMixin, MutableSequence):
    def __init__(self, items=()):
        self._items = list(items)
    def __getitem__(self, i): return self._items[i]
    def __setitem__(self, i, v): self._items[i] = v
    def __delitem__(self, i): del self._items[i]
    def __len__(self): return len(self._items)
    def insert(self, i, v): self._items.insert(i, v)

b = Bag([1, 2])
b.append(3)
print(len(b), list(b), 2 in b, b.pop(), b.to_json())
